# Code generated by Claude
"""
Forced slip in the simulator (design plan 8 D7, close-out F4): one pick with the grip force overridden to 2 N for this run only, the drop monitor and the oracle watching. A MEASUREMENT, not a pass/fail test.

    python experiments/forced_slip_test.py

The 2 N is the known creeping weak grip (design plan 10); GRIP_FORCE_TABLE is NOT changed (the pipeline's grip_force argument is used). The oracle checker decides the plan; retry_max is 0 so a failed
step ends the plan at once. Reports: the outcome, the plan failure, every attempt, the drop monitor's log (the time, the finger opening, the width held, the oracle's held? verdict at that tick), the
oracle's held? verdict at the pick's close, the finger opening and the beaker's height over time (every 0.25 s from the close to the end). If 2 N does not slip this says so; nothing is tuned.
"""

import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src.episode_runner import run_episode  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import ORCH_CFG  # noqa: E402


def main():
    sim = load_task(cameras=True)
    task = make_pipeline_task(checker="oracle", grip_force=2.0, orch_cfg={**ORCH_CFG, "retry_max": 0})
    model, data = sim.model, sim.data
    fq = int(model.jnt_qposadr[arm_ids(model, "left")["finger_jnt"][0]])
    samples, last = [], [-1.0]

    def extra(m, d):
        def step(obs):
            pipe = task["pipeline"]
            st = pipe["orchestrator"]["state"] if pipe else None
            if st and any(v["event"] == "gripper_closed" for v in st["verdicts"]) and obs["time"] - last[0] >= 0.25:
                last[0] = obs["time"]
                samples.append((obs["time"], float(d.qpos[fq]), float(d.site("beaker_base").xpos[2])))
            return None
        return {"sampler": {"step": step}}
    s = run_episode(task, model, data, extra_sources=extra)
    state = task["pipeline"]["orchestrator"]["state"]
    print(f"\noutcome {s['outcome']}   plan failure: {state['failure']}")
    print(f"attempts: {[(a['segment'], a['attempt'], a['outcome'], a['reason'][:90], a['oracle_passed']) for a in state['attempts']]}")
    print(f"verdicts: {[(v['event'], v['decides'], v['passed'], v['reason'][:60]) for v in state['verdicts']]}")
    print(f"drop monitor log: {state['monitors'] if state['monitors'] else 'NOTHING LOGGED (it did not fire)'}")
    print("finger opening (mm) and beaker base height (mm) from the pick's close, every 0.25 s:")
    for t, f, z in samples[:40]:
        print(f"  t={t:7.2f}  finger {1000 * f:6.2f}  beaker z {1000 * z:7.1f}")


if __name__ == "__main__":
    main()
